'use strict';
const $=id=>document.getElementById(id);
const HEROES=[{id:'sentinel',name:'อัศวินรอยแยก',role:'ไฟต์เตอร์ · อึดและโจมตีใกล้',icon:'⚔',hp:1400,damage:65,range:90,speed:190,q:'ฟันวงกว้าง',e:'พายุคมดาบ',position:'off',details:'Q: ฟันรอบตัว · E: หมุนโจมตีรอบตัวต่อเนื่อง 3 วินาที'}, {id:'arcanist',name:'จอมเวทดารา',role:'เมจ · สกิลโจมตีเป็นวงกว้าง',icon:'✦',hp:950,damage:48,range:235,speed:190,q:'ระเบิดดารา',e:'ดาวตก',position:'mid',details:'Q: ระเบิดเวทวงกว้าง · E: ดาวตกทำความเสียหายหนัก'}, {id:'ranger',name:'นักล่าแสง',role:'แครี่ · ยิงต่อเนื่องจากระยะไกล',icon:'➶',hp:1000,damage:57,range:260,speed:205,q:'ลูกศรกระจาย',e:'พลังนักล่า',position:'carry',details:'Q: ยิงกระจายรอบตัว · E: ยิงเร็วและแรงขึ้น 6 วินาที'}, {id:'bulwark',name:'ผู้พิทักษ์ศิลา',role:'แทงก์ · รับดาเมจและเปิดไฟต์',icon:'⬡',hp:1850,damage:45,range:85,speed:175,q:'แผ่นดินสะเทือน',e:'เกราะศิลา',position:'roam',details:'Q: สตันศัตรูรอบตัว 1.2 วินาที · E: รับโล่ 800 หน่วย 6 วินาที'}, {id:'shade',name:'เงาคมมีด',role:'แอสซาซิน · ล้วงศัตรูและเคลื่อนที่ไว',icon:'♢',hp:980,damage:80,range:100,speed:225,q:'คมมีดเงา',e:'ล่าเงา',position:'jungle',details:'Q: ฟันรอบตัว · E: พุ่งหาศัตรูใกล้สุด แรงขึ้นเมื่อเป้าหมายเลือดน้อย'}, {id:'oracle',name:'ผู้เยียวยาแสง',role:'ซัพพอร์ต · ฮีลและปกป้องทีม',icon:'✧',hp:1050,damage:40,range:210,speed:190,q:'แสงเยียวยา',e:'พรแห่งแสง',position:'roam',details:'Q: ฮีลพันธมิตรใกล้ตัว · E: ฮีลวงกว้างและให้โล่ทีม'}];
const CAMP_NAMES={power:'ผลึกพลัง',spirit:'ผลึกฟื้นฟู',boss:'ผู้เฝ้ารอยแยก'};
const POSITIONS={off:'ออฟเลน',mid:'เลนกลาง',carry:'แครี่',jungle:'ป่า',roam:'โรม'};
const portrait=new Image(),terrain=new Image();portrait.src='assets/heroes-atlas.png';terrain.src='assets/battlefield.png';
const ITEMS=[{id:'blade',name:'ดาบรอยแยก',icon:'⚔',desc:'โจมตี +25',cost:350,damage:25},{id:'boots',name:'รองเท้าลม',icon:'»',desc:'เดินเร็ว +30',cost:250,speed:30},{id:'armor',name:'เกราะพิทักษ์',icon:'⬡',desc:'เลือด +400',cost:400,hp:400},{id:'orb',name:'ผลึกดารา',icon:'✦',desc:'สกิลแรง +30%',cost:450,spell:.3},{id:'fang',name:'เขี้ยวนักล่า',icon:'♢',desc:'ดูดเลือด +12%',cost:400,leech:.12},{id:'haste',name:'นาฬิกากาล',icon:'◷',desc:'คูลดาวน์ลด 15%',cost:350,cdr:.15}];
const canvas=$('arena'),ctx=canvas.getContext('2d');
const WIDTH=1500,HEIGHT=1000;
const BLUE='#60e4db',RED='#ff9168',PURPLE='#c598ff';
const ROUTES=[[[120,840],[150,210],[700,180],[1380,160]],[[120,840],[750,500],[1380,160]],[[120,840],[800,820],[1350,790],[1380,160]]];
let selected=HEROES[0],view={scale:1,x:0,y:0,width:0,height:0};
function chooseHero(id){selected=HEROES.find(h=>h.id===id)||HEROES[0];$('heroName').textContent=selected.name;$('heroRole').textContent=selected.role;$('heroDetails').textContent=selected.details;$('position').value=selected.position;$('heroStats').innerHTML=`<div class="stat"><span>พลังชีวิต</span><b>${selected.hp}</b></div><div class="stat"><span>พลังโจมตี</span><b>${selected.damage}</b></div><div class="stat"><span>ระยะโจมตี</span><b>${selected.range}</b></div><div class="stat"><span>ความเร็ว</span><b>${selected.speed}</b></div>`;document.querySelectorAll('.hero-card').forEach(b=>{b.classList.toggle('selected',b.dataset.hero===selected.id);b.setAttribute('aria-pressed',String(b.dataset.hero===selected.id));b.querySelector('.check').textContent=b.dataset.hero===selected.id?'✓':'';});$('qName').textContent=selected.q;$('eName').textContent=selected.e;document.querySelector('[data-action="q"]').title=selected.details;$('wName').textContent='พุ่ง';}
$('heroes').innerHTML=HEROES.map((h,i)=>`<button class="hero-card" data-hero="${h.id}" style="--portrait-x:${i%3*50}%;--portrait-y:${i<3?0:100}%"><span class="check"></span><span class="hero-symbol">${h.icon}</span><b>${h.name}</b><small>${h.role.split(' · ')[0]}</small></button>`).join('');
document.querySelectorAll('[data-hero]').forEach(b=>b.onclick=()=>chooseHero(b.dataset.hero));
$('items').innerHTML=ITEMS.map(i=>`<button class="item" data-item="${i.id}" disabled><span class="item-icon">${i.icon}</span><span class="item-info"><b>${i.name}</b><small>${i.desc}</small></span><em>${i.cost} G</em></button>`).join('');
function resize(){const r=canvas.getBoundingClientRect(),dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(r.width*dpr);canvas.height=Math.round(r.height*dpr);view={width:r.width,height:r.height,scale:Math.min(r.width/WIDTH,r.height/HEIGHT),x:0,y:0};view.x=(r.width-WIDTH*view.scale)/2;view.y=(r.height-HEIGHT*view.scale)/2;ctx.setTransform(dpr,0,0,dpr,0,0);draw();}
function ground(){ctx.fillStyle='#0b1923';ctx.fillRect(0,0,WIDTH,HEIGHT);if(terrain.complete&&terrain.naturalWidth){ctx.drawImage(terrain,0,0,WIDTH,HEIGHT);ctx.fillStyle='#04121b38';ctx.fillRect(0,0,WIDTH,HEIGHT);for(const route of ROUTES){ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#a8efe733';ctx.lineWidth=3;ctx.setLineDash([8,12]);ctx.stroke();ctx.setLineDash([]);}return;}ctx.strokeStyle='#17303b';ctx.lineWidth=1;for(let x=0;x<WIDTH;x+=75){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,HEIGHT);ctx.stroke();}for(let y=0;y<HEIGHT;y+=75){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(WIDTH,y);ctx.stroke();}for(const route of ROUTES){ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.strokeStyle='#233c43';ctx.lineWidth=66;ctx.lineJoin='round';ctx.stroke();}}
function draw(){if(game&&view.width<650){view.scale=.72;const p=game.player;view.x=Math.min(0,Math.max(view.width-WIDTH*view.scale,view.width/2-p.x*view.scale));view.y=Math.min(0,Math.max(view.height-HEIGHT*view.scale,view.height*.46-p.y*view.scale));}else {view.scale=Math.min(view.width/WIDTH,view.height/HEIGHT);view.x=(view.width-WIDTH*view.scale)/2;view.y=(view.height-HEIGHT*view.scale)/2;}ctx.save();ctx.clearRect(0,0,view.width,view.height);ctx.translate(view.x,view.y);ctx.scale(view.scale,view.scale);ground();renderBattle();ctx.restore();if(game&&view.width<650)renderMini();}
$('helpBtn').onclick=()=>$('help').showModal();$('closeHelp').onclick=$('understood').onclick=()=>$('help').close();
chooseHero(selected.id);new ResizeObserver(resize).observe(canvas);

let game=null,keys=new Set(),pointer={x:750,y:500},joystick={x:0,y:0},effects=[],lastTime=0,noticeTimer=0,sound=false,audioContext=null,shopPaused=false;
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y),home=team=>team===0?{x:120,y:840}:{x:1380,y:160};
function routePoint(lane,t){const r=ROUTES[lane],lengths=r.slice(1).map((p,i)=>Math.hypot(p[0]-r[i][0],p[1]-r[i][1])),total=lengths.reduce((a,b)=>a+b,0);let at=t*total;for(let i=0;i<lengths.length;i++){if(at<=lengths[i])return {x:r[i][0]+(r[i+1][0]-r[i][0])*at/lengths[i],y:r[i][1]+(r[i+1][1]-r[i][1])*at/lengths[i]};at-=lengths[i];}return {x:r.at(-1)[0],y:r.at(-1)[1]};}
function notify(msg){if(typeof net!=='undefined'&&net.suppressNotice)return;$('announcement').textContent=msg;$('announcement').classList.add('show');noticeTimer=3;}
function tone(freq=440,length=.06){if(!sound)return;try{audioContext ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.04,audioContext.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+length);o.connect(g);g.connect(audioContext.destination);o.start();o.stop(audioContext.currentTime+length);}catch{}}
function entity(type,team,x,y,extra={}){return {id:game.nextId++,type,team,x,y,hp:240,maxHp:240,damage:20,speed:105,range:80,attack:0,radius:12,dead:false,...extra};}
function hero(team,lane,def,player=false){const h=home(team),difficulty=$('difficulty').value,mult=team===1?(difficulty==='easy'?.78:difficulty==='hard'?1.18:1):1;return entity('hero',team,h.x+(team===0?35:-35),h.y+(lane-1)*25,{def,player,lane,position:def.position,enchant:'fury',shield:0,shieldTime:0,stun:0,spirit:0,hp:def.hp*mult,maxHp:def.hp*mult,damage:def.damage*mult,speed:def.speed,range:def.range,radius:19,level:1,xp:0,gold:500,kills:0,deaths:0,assists:0,inventory:[],cd:{q:0,w:0,e:0},spell:1,leech:0,cdr:0,respawn:0,recall:0,buff:0,rage:0,spin:0,spinTick:0,walkIndex:team===0?1:ROUTES[lane].length-2});}
function startGame(){document.querySelector('.team.blue').firstChild.textContent='ทีมคุณ ';document.querySelector('.team.orange').lastChild.textContent=' ศัตรู';keys.clear();effects=[];joystick={x:0,y:0};game={time:0,paused:false,finished:false,entities:[],nextId:1,kills:[0,0],wave:3,player:null,towerKills:0,teamBuffs:[0,0],objectiveKills:[0,0]};for(let team=0;team<2;team++){const base=home(team);game.entities.push(entity('base',team,base.x,base.y,{hp:2300,maxHp:2300,range:190,damage:100,speed:0,radius:43}));for(let lane=0;lane<3;lane++)for(let n=0;n<2;n++){const p=routePoint(lane,team===0?(n===0?.20:.34):(n===0?.80:.66));game.entities.push(entity('tower',team,p.x,p.y,{hp:1100,maxHp:1100,damage:85,range:205,speed:0,radius:25,lane,inner:n===0}));}for(let i=0;i<5;i++){const def=team===0&&i===0?selected:HEROES[(i+team)%3],h=hero(team,i===0?1:[0,2,1,0][i-1],def,team===0&&i===0);game.entities.push(h);if(h.player)game.player=h;}}
for(const [camp,x,y] of [['power',640,330],['spirit',860,670],['boss',750,500]]){const boss=camp==='boss';game.entities.push(entity('monster',2,x,y,{camp,hp:boss?2800:900,maxHp:boss?2800:900,damage:boss?65:35,range:boss?165:130,speed:0,radius:boss?38:25,dead:boss,respawn:boss?60:0,lastDamaged:0}));}
const p=game.player;applyLoadout(p,$('rune').value,$('enchant').value||'fury',$('position').value||selected.position);const occupied=p.position;const slots=Object.keys(POSITIONS).filter(x=>x!==occupied);const teamHeroes={off:'sentinel',mid:'arcanist',carry:'ranger',jungle:'shade',roam:'oracle'};for(let team=0;team<2;team++){const others=game.entities.filter(e=>e.type==='hero'&&e.team===team&&!e.player);const positions=team===0?slots:Object.keys(POSITIONS);for(let i=0;i<others.length;i++){const e=others[i],def=HEROES.find(h=>h.id===teamHeroes[positions[i]]);Object.assign(e,hero(team,laneFor(positions[i]),def));applyLoadout(e,'power','fury',positions[i]);}}
$('lobby').hidden=true;$('result').hidden=true;$('pauseOverlay').hidden=true;$('playerHud').hidden=false;$('pauseBtn').hidden=false;$('shopBtn').hidden=false;$('scoreBtn').hidden=false;document.body.classList.add('playing');$('phase').textContent='ดันเลน · ทำลายฐาน';$('modeLabel').textContent='5 ต่อ 5 · '+({easy:'ฝึกหัด',normal:'ปกติ',hard:'ท้าทาย'}[$('difficulty').value]);notify('เริ่มการต่อสู้! เดินตามครีปไปโจมตีป้อม');canvas.focus({preventScroll:true});syncHud();tone(650,.15);}
function lobby(){game=null;effects=[];keys.clear();$('lobby').hidden=false;$('result').hidden=true;$('pauseOverlay').hidden=true;$('playerHud').hidden=true;$('pauseBtn').hidden=true;$('shopBtn').hidden=true;$('scoreBtn').hidden=true;if($('scoreboard').open)$('scoreboard').close();$('buffs').textContent='';$('objectiveStatus').textContent='';$('modeLabel').textContent='5 ต่อ 5 · คุณและบอต';$('shopBtn').textContent='ร้านค้า';document.body.classList.remove('playing','shop-open');shopPaused=false;$('announcement').classList.remove('show');$('timer').textContent='00:00';$('blueKills').textContent=$('redKills').textContent='0';$('phase').textContent='เตรียมเข้าสู่สนาม';$('gold').textContent='0 G';$('inventory').innerHTML='';delete $('inventory').dataset.items;document.querySelectorAll('[data-item]').forEach(b=>b.disabled=true);}
function pause(value){if(!game||game.finished)return;game.paused=value;$('pauseOverlay').hidden=!value;keys.clear();joystick={x:0,y:0};$('joystick').firstElementChild.style.transform='';}
function move(e,x,y,dt){const dx=x-e.x,dy=y-e.y,d=Math.hypot(dx,dy),step=Math.min(d,e.speed*dt);if(d>1){e.x+=dx/d*step;e.y+=dy/d*step;}e.x=Math.max(45,Math.min(WIDTH-45,e.x));e.y=Math.max(45,Math.min(HEIGHT-45,e.y));}
function laneFor(position){return position==='off'?0:position==='carry'||position==='roam'?2:1;}
function applyLoadout(e,rune='power',enchant='fury',position=e.def.position){e.position=position;e.lane=laneFor(position);e.walkIndex=e.team===0?1:ROUTES[e.lane].length-2;e.enchant=enchant;e.rune=rune;if(rune==='power')e.damage*=1.15;if(rune==='vitality'){e.maxHp*=1.2;e.hp=e.maxHp;}if(rune==='speed')e.speed*=1.15;}
function enemies(e,range,includeNeutral=false){return game.entities.filter(t=>!t.dead&&t.team!==e.team&&(t.team!==2||includeNeutral)&&distance(e,t)<=range+t.radius);}
function attackTarget(e){const list=enemies(e,e.range,true).filter(t=>t.type!=='base'||baseOpen(t.team)),mode=e.remoteHuman?e.control?.targetMode:$('targetMode').value;return list.sort((a,b)=>mode==='hero'?((a.type==='hero'?0:1)-(b.type==='hero'?0:1)||distance(e,a)-distance(e,b)):mode==='lowest'?a.hp/a.maxHp-b.hp/b.maxHp||distance(e,a)-distance(e,b):distance(e,a)-distance(e,b))[0];}
function targets(e){return enemies(e,e.range,e.player).filter(t=>t.type!=='base'||baseOpen(t.team));}
function baseOpen(team){return [0,1,2].some(lane=>!game.entities.some(t=>t.type==='tower'&&t.team===team&&t.lane===lane&&!t.dead));}
function heal(e,amount){e.hp=Math.min(e.maxHp,e.hp+amount);}
function gainXp(e,amount){if(e.type!=='hero')return;e.xp+=amount;while(e.xp>=100+e.level*60&&e.level<15){e.xp-=100+e.level*60;e.level++;e.maxHp+=90;e.hp=Math.min(e.maxHp,e.hp+200);e.damage+=6;if(e.player){notify('เลเวล '+e.level+' · พลังชีวิตและพลังโจมตีเพิ่มขึ้น');tone(880,.1);}}}
function damage(target,amount,source){if(target.dead)return;if(target.type==='base'&&!baseOpen(target.team)){if(source.player)notify('ทำลายป้อมทั้งสองในเลนเดียวกัน เพื่อเปิดฐาน');return;}if(target.enchant==='guard')amount*=.92;if(source.enchant==='fury'&&target.hp/target.maxHp<.4)amount*=1.08;if(target.shield>0){const absorbed=Math.min(target.shield,amount);target.shield-=absorbed;amount-=absorbed;}target.lastDamaged=game.time;target.hp-=amount;if(target.type==='hero')target.recall=0;if(source.type==='hero'){target.hitBy ||= {};target.hitBy[source.id]=game.time;}if(source.player)target.playerHit=game.time;
effects.push({type:'text',x:target.x,y:target.y-25,text:Math.round(amount),color:source.team===0?BLUE:RED,life:.6,max:.6});if(source.type==='hero'&&source.leech)heal(source,amount*source.leech);
if(target.hp>0)return;target.hp=0;target.dead=true;let reward=0,xp=0;if(target.type==='hero'){target.deaths++;target.respawn=6+target.level*.6;target.destination=null;if(source.team<2)game.kills[source.team]++;reward=200;xp=140;if(source.type==='hero')source.kills++;for(const h of game.entities.filter(h=>h.type==='hero'&&h.team===source.team&&h.id!==source.id&&!h.dead&&target.hitBy?.[h.id]!==undefined&&game.time-target.hitBy[h.id]<6)){h.assists++;h.gold+=75;gainXp(h,70);}if(target.player){notify('คุณถูกสังหาร · เกิดใหม่ใน '+Math.ceil(target.respawn)+' วินาที');tone(180,.25);}else if(source.player){notify('สังหารศัตรู! +200 G');tone(720,.12);}}
else if(target.type==='minion'){reward=40;xp=35;}else if(target.type==='tower'){reward=150;xp=100;if(source.team===0){game.towerKills++;notify('ป้อมศัตรูถูกทำลาย!');}else notify('ป้อมทีมคุณถูกทำลาย');for(const h of game.entities.filter(h=>h.type==='hero'&&h.team===source.team))h.gold+=75;}
else if(target.type==='monster'){target.respawn=target.camp==='boss'?90:35;if(target.camp==='boss'){reward=0;xp=0;if(source.team<2){game.teamBuffs[source.team]=45;game.objectiveKills[source.team]++;for(const h of game.entities.filter(h=>h.type==='hero'&&h.team===source.team)){h.gold+=180;gainXp(h,160);if(!h.dead){h.shield=Math.max(h.shield,300);h.shieldTime=Math.max(h.shieldTime,8);}}notify((source.team===game.player.team?'ทีมคุณ':'ศัตรู')+'พิชิตผู้เฝ้ารอยแยก · ตีป้อมแรงขึ้น 25% นาน 45 วินาที');}}else{reward=130;xp=100;if(source.type==='hero'){if(target.camp==='spirit')source.spirit=30;else source.buff=30;heal(source,200);if(source.player)notify(target.camp==='spirit'?'บัฟฟื้นฟู · ฮีลต่อเนื่องและคูลดาวน์ไวขึ้น 30 วินาที':'บัฟพลัง · โจมตีแรงขึ้น 20% นาน 30 วินาที');}}}
else if(target.type==='base'){endGame(source.team===0);return;}
if(source.type==='hero'){source.gold+=reward;gainXp(source,xp);if(source.enchant==='recovery'&&target.type==='hero')heal(source,source.maxHp*.1);}else for(const h of game.entities.filter(h=>h.type==='hero'&&h.team===source.team&&!h.dead&&distance(h,target)<300)){h.gold+=Math.round(reward*.5);gainXp(h,xp*.5);}}
function strike(e,t){if(e.attack>0||e.stun>0||!t||t.dead)return;e.attack=e.type==='hero'?(e.def.id==='ranger'?.75:1)*(e.rage>0?.48:1):e.type==='minion'?1.3:1;const dmg=e.damage*(e.buff>0?1.2:1)*(e.rage>0?1.4:1)*(game.teamBuffs?.[e.team]>0&&['tower','base'].includes(t.type)?1.25:1);effects.push({type:'shot',x:e.x,y:e.y,tx:t.x,ty:t.y,color:e.team===0?BLUE:e.team===1?RED:PURPLE,life:.2,max:.2});damage(t,dmg,e);if(e.player)tone(e.range>150?450:260);}
function attackPlayer(){if(!game||game.paused||game.finished||game.player.dead)return;const p=game.player;p.recall=0;const target=attackTarget(p);strike(p,target);if(!target)notify('ไม่มีศัตรูในระยะ · เดินเข้าใกล้เป้าหมาย');}
function useSkill(key,actor=null,aim=pointer){if(!game||game.paused||game.finished||!['q','w','e'].includes(key))return false;const p=actor||game.player;if(p.dead||p.stun>0||p.cd[key]>0)return false;p.recall=0;const color=p.team===0?BLUE:RED;let cooldown=0;if(key==='w'){let dx=aim.x-p.x,dy=aim.y-p.y;if(p.player&&Math.hypot(joystick.x,joystick.y)>.1){dx=joystick.x;dy=joystick.y;}else if(p.player&&(keys.has('a')||keys.has('d')||keys.has('w')||keys.has('s')||[...keys].some(k=>k.startsWith('arrow')))){dx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0);dy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0);}const len=Math.hypot(dx,dy)||1;effects.push({type:'shot',x:p.x,y:p.y,tx:p.x+dx/len*210,ty:p.y+dy/len*210,color,life:.35,max:.35});p.x=Math.max(45,Math.min(WIDTH-45,p.x+dx/len*210));p.y=Math.max(45,Math.min(HEIGHT-45,p.y+dy/len*210));p.destination=null;cooldown=8;}
if(key==='q'){const radius=['sentinel','shade','bulwark'].includes(p.def.id)?185:300,amount=(p.def.id==='arcanist'?180:140)+p.level*15;if(p.def.id==='oracle'){for(const t of game.entities.filter(t=>t.team===p.team&&t.type==='hero'&&!t.dead&&distance(p,t)<300))heal(t,(220+p.level*20)*p.spell);}else for(const t of enemies(p,radius,true)){damage(t,amount*p.spell,p);if(p.def.id==='bulwark'&&t.type==='hero')t.stun=1.2;}effects.push({type:'ring',x:p.x,y:p.y,radius,color:p.def.id==='oracle'?'#96ffb7':p.def.id==='arcanist'?PURPLE:color,life:.5,max:.5});cooldown=6;}
if(key==='e'){cooldown=20;if(p.def.id==='ranger'){p.rage=6;if(p.player)notify('พลังนักล่า · ยิงเร็วและแรงขึ้น 6 วินาที');}else if(p.def.id==='sentinel'){p.spin=3;p.spinTick=0;if(p.player)notify('พายุคมดาบ · โจมตีรอบตัว 3 วินาที');}else if(p.def.id==='bulwark'){p.shield=800+p.level*30;p.shieldTime=6;if(p.player)notify('เกราะศิลา · ได้รับโล่ 6 วินาที');}else if(p.def.id==='oracle'){for(const t of game.entities.filter(t=>t.team===p.team&&t.type==='hero'&&!t.dead&&distance(p,t)<450)){heal(t,(450+p.level*30)*p.spell);t.shield=250;t.shieldTime=5;}effects.push({type:'ring',x:p.x,y:p.y,radius:450,color:'#96ffb7',life:.9,max:.9});}else if(p.def.id==='shade'){const list=enemies(p,380,true).filter(t=>t.type==='hero'||t.type==='monster'||t.type==='minion').sort((a,b)=>(a.type==='hero'?0:1)-(b.type==='hero'?0:1)||distance(p,a)-distance(p,b));const t=list[0];if(!t){if(p.player)notify('ไม่มีศัตรูในระยะล่าเงา');return false;}p.x=Math.max(45,Math.min(WIDTH-45,t.x-35));p.y=t.y;damage(t,(360+p.level*25)*(t.hp/t.maxHp<.35?1.5:1)*p.spell,p);effects.push({type:'ring',x:p.x,y:p.y,radius:100,color:'#eaa7ff',life:.6,max:.6});}else{for(const t of enemies(p,350,true))damage(t,(380+p.level*25)*p.spell,p);effects.push({type:'ring',x:p.x,y:p.y,radius:350,color:PURPLE,life:.9,max:.9});}}
p.cd[key]=cooldown*(1-Math.min(.6,p.cdr));if(p.player)tone(key==='e'?140:540,.15);return true;}
function recall(){if(!game||game.paused||game.finished||game.player.dead)return;game.player.recall=4;game.player.destination=null;notify('กำลังกลับฐาน · ยืนนิ่ง 4 วินาที');}
function buy(id,actor=null){if(!game||game.finished)return {ok:false,reason:'ยังไม่เริ่มแมตช์'};const p=actor||game.player,i=ITEMS.find(i=>i.id===id);if(!i)return {ok:false,reason:'ไม่พบไอเทม'};if(p.inventory.length>=6){if(p.player)notify('ไอเทมเต็ม 6 ช่องแล้ว');return {ok:false,reason:'ช่องไอเทมเต็ม'};}if(p.gold<i.cost){if(p.player)notify('เงินไม่พอซื้อ '+i.name);return {ok:false,reason:'เงินไม่พอ'};}p.gold-=i.cost;p.inventory.push(i);p.damage+=i.damage||0;p.speed+=i.speed||0;if(i.hp){p.maxHp+=i.hp;heal(p,i.hp);}p.spell+=i.spell||0;p.leech+=i.leech||0;p.cdr+=i.cdr||0;if(p.player){notify('ซื้อ '+i.name+' แล้ว');syncHud();tone(820);}return {ok:true,gold:Math.floor(p.gold),items:p.inventory.map(i=>i.id)};}
function sell(slot,actor=null){if(!game||game.finished)return {ok:false};const p=actor||game.player;if(!Number.isInteger(slot)||!p.inventory[slot])return {ok:false};const [i]=p.inventory.splice(slot,1);p.gold+=Math.floor(i.cost*.6);p.damage-=i.damage||0;p.speed-=i.speed||0;p.maxHp-=i.hp||0;p.hp=Math.min(p.hp,p.maxHp);p.spell-=i.spell||0;p.leech-=i.leech||0;p.cdr-=i.cdr||0;if(p.player){notify('ขาย '+i.name+' · ได้เงินคืน 60%');syncHud();}return {ok:true};}
function spawnWave(){for(let team=0;team<2;team++)for(let lane=0;lane<3;lane++)for(let n=0;n<3;n++){const h=home(team);game.entities.push(entity('minion',team,h.x+(team===0?1:-1)*n*20,h.y+n*12,{lane,walkIndex:team===0?1:ROUTES[lane].length-2,damage:20+game.time/40,hp:240+game.time*.3,maxHp:240+game.time*.3}));}}
function followLane(e,dt){const route=ROUTES[e.lane];let p=route[e.walkIndex];if(!p){const b=home(1-e.team);move(e,b.x,b.y,dt);return;}if(distance(e,{x:p[0],y:p[1]})<35)e.walkIndex+=e.team===0?1:-1;move(e,p[0],p[1],dt);}
function updateBot(e,dt){if(e.remoteHuman&&!e.autoPilot||e.stun>0)return;const h=home(e.team);if(e.type==='hero'){const build=e.def.id==='arcanist'||e.def.id==='oracle'?['orb','boots','haste','armor','orb','fang']:e.def.id==='bulwark'?['armor','boots','armor','haste','blade','fang']:['blade','boots','fang','armor','blade','haste'];if(e.inventory.length<6)buy(build[e.inventory.length],e);if(e.hp<e.maxHp*.25)e.retreat=true;if(e.retreat){move(e,h.x,h.y,dt);if(e.hp>e.maxHp*.8){e.retreat=false;e.walkIndex=e.team===0?1:ROUTES[e.lane].length-2;}return;}if(e.position==='jungle'){const camp=game.entities.filter(t=>t.type==='monster'&&!t.dead&&(t.camp!=='boss'||e.level>=3&&e.hp/e.maxHp>.65)).sort((a,b)=>distance(e,a)-distance(e,b))[0];if(camp&&!enemies(e,300).some(t=>t.type==='hero')){if(distance(e,camp)<e.range+camp.radius){strike(e,camp);useSkill('q',e);}else move(e,camp.x,camp.y,dt);return;}}}
const search=e.type==='hero'?310:e.range+20,candidates=enemies(e,search).filter(t=>t.type!=='base'||baseOpen(t.team));candidates.sort((a,b)=>distance(e,a)-distance(e,b));const t=candidates[0];if(t){if(e.type==='hero'&&t.type==='tower'&&!game.entities.some(m=>m.team===e.team&&m.type==='minion'&&!m.dead&&distance(m,t)<t.range)){const dx=e.x-t.x,dy=e.y-t.y,len=Math.hypot(dx,dy)||1;move(e,t.x+dx/len*(t.range+60),t.y+dy/len*(t.range+60),dt);return;}if(distance(e,t)<=e.range+t.radius)strike(e,t);else move(e,t.x,t.y,dt);if(e.type==='hero'&&distance(e,t)<(e.def.id==='oracle'?400:200)){useSkill('q',e);if(t.type==='hero'||e.hp<e.maxHp*.5)useSkill('e',e);}}else followLane(e,dt);}
function update(dt){if(!game||game.paused||game.finished)return;game.time+=dt;game.teamBuffs=(game.teamBuffs||[0,0]).map(t=>Math.max(0,t-dt));game.wave-=dt;if(game.wave<=0){spawnWave();game.wave=16;}noticeTimer-=dt;if(noticeTimer<=0)$('announcement').classList.remove('show');const p=game.player;
for(const e of game.entities){if(e.dead){if(e.type==='hero'||e.type==='monster'){e.respawn-=dt;if(e.respawn<=0){e.dead=false;e.hp=e.maxHp;e.attack=0;if(e.type==='hero'){const h=home(e.team);e.x=h.x;e.y=h.y;e.walkIndex=e.team===0?1:ROUTES[e.lane].length-2;e.cd={q:0,w:0,e:0};e.spirit=e.buff=e.rage=e.spin=e.recall=e.stun=e.shield=e.shieldTime=0;e.hitBy={};if(e.player)notify('เกิดใหม่แล้ว · กลับไปช่วยทีม!');}}}continue;}e.attack=Math.max(0,e.attack-dt);
if(e.type==='hero'){e.gold+=3*dt;for(const k of ['q','w','e'])e.cd[k]=Math.max(0,e.cd[k]-dt*(e.spirit>0?1.25:1));if(e.spirit>0)heal(e,e.maxHp*.015*dt);e.spirit=Math.max(0,(e.spirit||0)-dt);e.buff=Math.max(0,e.buff-dt);e.rage=Math.max(0,e.rage-dt);e.stun=Math.max(0,e.stun-dt);e.shieldTime=Math.max(0,e.shieldTime-dt);if(e.shieldTime<=0)e.shield=0;if(distance(e,home(e.team))<105)heal(e,e.maxHp*.22*dt);if(!e.player&&!e.remoteHuman&&e.level<Math.min(15,1+Math.floor(game.time/40)))gainXp(e,100+e.level*60);if(e.spin>0){e.spin-=dt;e.spinTick-=dt;if(e.spinTick<=0){e.spinTick=.5;for(const t of enemies(e,200,true))damage(t,(75+e.level*8)*e.spell,e);effects.push({type:'ring',x:e.x,y:e.y,radius:200,color:e.team===0?BLUE:RED,life:.45,max:.45});}}}
if(e.type==='tower'||e.type==='base'){const list=enemies(e,e.range).filter(t=>t.type==='hero'||t.type==='minion').sort((a,b)=>(a.type==='minion'?0:1)-(b.type==='minion'?0:1)||distance(e,a)-distance(e,b));strike(e,list[0]);}
else if(e.type==='monster'){const list=enemies(e,e.range).filter(t=>t.type==='hero').sort((a,b)=>distance(e,a)-distance(e,b));strike(e,list[0]);if(!list.length&&game.time-(e.lastDamaged||0)>3)heal(e,e.maxHp*.15*dt);}
else if(!e.player)updateBot(e,dt);
}
for(const controlled of game.entities.filter(e=>e.type==='hero'&&(e.player||e.remoteHuman&&!e.autoPilot))){if(controlled.dead||controlled.stun>0)continue;const p=controlled,input=p.remoteHuman?p.control:null;let dx=input?.move?.x??((keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joystick.x),dy=input?.move?.y??((keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joystick.y);const len=Math.hypot(dx,dy);if(len>.1){p.destination=null;p.recall=0;move(p,p.x+dx/len*200,p.y+dy/len*200,dt);}else if(p.destination){p.recall=0;if(distance(p,p.destination)>8)move(p,p.destination.x,p.destination.y,dt);else p.destination=null;}
if(input?.attack||(!p.remoteHuman&&keys.has(' '))){const t=attackTarget(p);p.recall=0;strike(p,t);}if(p.recall>0){p.recall-=dt;if(p.recall<=0){const h=home(p.team);p.x=h.x;p.y=h.y;if(p.player)notify('กลับฐานแล้ว · ฟื้นฟูพลังชีวิต');}}}
effects.forEach(f=>f.life-=dt);effects=effects.filter(f=>f.life>0);game.entities=game.entities.filter(e=>!e.dead||e.type!=='minion');syncHud();}
function syncHud(){if(!game)return;const p=game.player;$('gold').textContent=Math.floor(p.gold)+' G';$('buffs').textContent=[p.buff>0?'พลัง '+Math.ceil(p.buff)+' วิ':'',p.spirit>0?'ฟื้นฟู '+Math.ceil(p.spirit)+' วิ':'',game.teamBuffs?.[p.team]>0?'บัฟทีม '+Math.ceil(game.teamBuffs[p.team])+' วิ':''].filter(Boolean).join(' · ');const boss=game.entities.find(e=>e.camp==='boss');$('objectiveStatus').textContent=boss?(boss.dead?'บอสเกิดใน '+Math.ceil(boss.respawn)+' วิ':'บอสพร้อมให้ท้าทาย'):'';if($('scoreboard').open)renderScoreboard();$('timer').textContent=String(Math.floor(game.time/60)).padStart(2,'0')+':'+String(Math.floor(game.time%60)).padStart(2,'0');$('blueKills').textContent=game.kills[0];$('redKills').textContent=game.kills[1];$('playerLevel').textContent='LV '+p.level;$('hpFill').style.width=Math.max(0,p.hp/p.maxHp*100)+'%';$('hpText').textContent=Math.ceil(p.hp)+' / '+Math.round(p.maxHp);$('xpFill').style.width=(p.level===15?100:p.xp/(100+p.level*60)*100)+'%';$('phase').textContent=p.dead?'เกิดใหม่ '+Math.ceil(p.respawn)+' วิ':p.recall>0?'กลับฐาน '+p.recall.toFixed(1)+' วิ':'ดันเลน · ทำลายฐาน';
for(const b of document.querySelectorAll('[data-action]')){const k=b.dataset.action,cd=p.cd[k]||0;b.disabled=p.dead||p.stun>0;const i=b.querySelector('i');if(i){b.classList.toggle('cooldown',cd>0);i.textContent=Math.ceil(cd);}}
document.querySelectorAll('[data-item]').forEach(b=>{const i=ITEMS.find(i=>i.id===b.dataset.item);b.disabled=p.gold<i.cost||p.inventory.length>=6||game.finished;});const signature=p.inventory.map(i=>i.id).join(',');if($('inventory').dataset.items!==signature){$('inventory').dataset.items=signature;$('inventory').innerHTML=p.inventory.map((i,slot)=>`<button data-sell="${slot}" title="ขาย ${i.name} ได้ ${Math.floor(i.cost*.6)} G" aria-label="ขาย ${i.name}">${i.icon}</button>`).join('')+Array.from({length:6-p.inventory.length},()=>'<span>·</span>').join('');document.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>sell(Number(b.dataset.sell)));}}
function endGame(blueWon){if(game.finished)return;game.finished=true;game.winner=blueWon?0:1;showResult();}
function showResult(){const p=game.player,win=game.winner===p.team;keys.clear();$('result').hidden=false;$('resultTitle').textContent=win?'ชัยชนะ':'พ่ายแพ้';$('resultTitle').style.color=win?BLUE:RED;$('resultDesc').textContent=win?'ทีมคุณทำลายฐานศัตรูสำเร็จ':'ฐานทีมคุณถูกทำลาย ลองแผนใหม่ในแมตช์ถัดไป';$('resultStats').innerHTML=`<div><b>${p.kills}/${p.deaths}/${p.assists}</b><span>K / D / A</span></div><div><b>${$('timer').textContent}</b><span>เวลาแข่งขัน</span></div><div><b>${p.level}</b><span>เลเวลฮีโร่</span></div>`;syncHud();tone(win?740:160,.4);}
function renderBattle(){if(!game)return;const p=game.player;if(!p.dead){ctx.beginPath();ctx.arc(p.x,p.y,p.range,0,Math.PI*2);ctx.strokeStyle=BLUE+'32';ctx.lineWidth=1.5;ctx.stroke();if(p.destination){ctx.strokeStyle=BLUE+'66';ctx.setLineDash([5,8]);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.destination.x,p.destination.y);ctx.stroke();ctx.setLineDash([]);ctx.beginPath();ctx.arc(p.destination.x,p.destination.y,7,0,Math.PI*2);ctx.stroke();}}
for(const e of game.entities){if(e.dead){if(e.type==='monster'){ctx.fillStyle='#c598ffbb';ctx.font='13px sans-serif';ctx.textAlign='center';ctx.fillText((CAMP_NAMES[e.camp]||'ผลึก')+' '+Math.ceil(e.respawn)+'s',e.x,e.y);}if(e.player){ctx.fillStyle=BLUE+'77';ctx.font='22px sans-serif';ctx.textAlign='center';ctx.fillText('เกิดใหม่ '+Math.ceil(e.respawn)+'s',e.x,e.y);}continue;}const color=e.team===0?BLUE:e.team===1?RED:PURPLE;ctx.save();ctx.translate(e.x,e.y);if(e.type==='tower'){ctx.fillStyle=color+'0c';ctx.beginPath();ctx.arc(0,0,e.range,0,Math.PI*2);ctx.fill();ctx.strokeStyle=color;ctx.lineWidth=3;ctx.fillStyle='#102331';ctx.beginPath();ctx.rect(-22,-22,44,44);ctx.fill();ctx.stroke();ctx.rotate(Math.PI/4);ctx.fillStyle=color;ctx.fillRect(-9,-9,18,18);ctx.rotate(-Math.PI/4);}else if(e.type==='base'){const open=baseOpen(e.team);ctx.strokeStyle=color;ctx.lineWidth=4;ctx.fillStyle=color+'25';ctx.beginPath();for(let i=0;i<6;i++){const angle=i*Math.PI/3;i?ctx.lineTo(Math.cos(angle)*43,Math.sin(angle)*43):ctx.moveTo(43,0);}ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=color;ctx.font='40px sans-serif';ctx.textAlign='center';ctx.fillText(open?'◇':'⬡',0,13);ctx.font='13px "Noto Sans Thai"';ctx.fillText(open?'ฐานเปิด':'ฐานมีเกราะ',0,75);}else if(e.type==='hero'){if(e.player){ctx.shadowColor=BLUE;ctx.shadowBlur=15;ctx.strokeStyle='#e1fffa';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,25,0,Math.PI*2);ctx.stroke();}ctx.fillStyle=e.player?BLUE:color+'bb';ctx.strokeStyle='#091420';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,19,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle='#081722';ctx.font='bold 22px sans-serif';ctx.textAlign='center';if(portrait.complete&&portrait.naturalWidth){const index=HEROES.findIndex(h=>h.id===e.def.id),cell=portrait.naturalWidth/3;ctx.save();ctx.beginPath();ctx.arc(0,0,18,0,Math.PI*2);ctx.clip();ctx.drawImage(portrait,(index%3+.12)*cell,(Math.floor(index/3)+.05)*cell,cell*.76,cell*.76,-19,-19,38,38);ctx.restore();}else ctx.fillText(e.def.icon,0,8);if(e.shield>0){ctx.strokeStyle='#a8dcff';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,31,0,Math.PI*2);ctx.stroke();}if(e.stun>0){ctx.fillStyle='#f0cd7c';ctx.font='22px sans-serif';ctx.fillText('✧',0,-49);}ctx.fillStyle=e.player?'#fff':color;ctx.font='12px "Noto Sans Thai",sans-serif';ctx.fillText(e.player?'คุณ · '+e.level:(e.clientName||(e.team===game.player.team?'พันธมิตร':'ศัตรู'))+' '+e.level,0,-36);if(e.buff>0||e.rage>0){ctx.strokeStyle=e.rage>0?'#f0cd7c':PURPLE;ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,29,0,Math.PI*2);ctx.stroke();}if(e.recall>0){ctx.strokeStyle=BLUE;ctx.lineWidth=4;ctx.beginPath();ctx.arc(0,0,35,-Math.PI/2,-Math.PI/2+(4-e.recall)/4*Math.PI*2);ctx.stroke();}}
else if(e.type==='monster'){const tint=e.camp==='boss'?'#f0cd7c':e.camp==='spirit'?'#96ffb7':PURPLE;ctx.strokeStyle=tint;ctx.lineWidth=3;ctx.fillStyle='#342749';ctx.beginPath();ctx.moveTo(0,-e.radius);ctx.lineTo(e.radius,0);ctx.lineTo(0,e.radius);ctx.lineTo(-e.radius,0);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle=tint;ctx.font='20px sans-serif';ctx.textAlign='center';ctx.fillText(e.camp==='boss'?'✧':'✦',0,7);ctx.font='13px sans-serif';ctx.fillText(CAMP_NAMES[e.camp]||'ผลึก',0,e.radius+20);}else{ctx.fillStyle=color;ctx.beginPath();ctx.arc(0,0,9,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#132533';ctx.lineWidth=2;ctx.stroke();}
const width=e.type==='minion'?24:e.type==='base'?80:e.type==='tower'?54:45,y=e.type==='base'?-60:e.type==='tower'?-36:e.type==='hero'?-29:-35;ctx.fillStyle='#02080f';ctx.fillRect(-width/2,y,width,5);ctx.fillStyle=color;ctx.fillRect(-width/2,y,width*Math.max(0,e.hp/e.maxHp),5);ctx.restore();}
for(const f of effects){ctx.globalAlpha=Math.max(0,f.life/f.max);if(f.type==='shot'){ctx.strokeStyle=f.color;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(f.x,f.y);ctx.lineTo(f.tx,f.ty);ctx.stroke();}if(f.type==='ring'){ctx.strokeStyle=f.color;ctx.fillStyle=f.color+'18';ctx.lineWidth=4;ctx.beginPath();ctx.arc(f.x,f.y,f.radius*(1-f.life/f.max*.25),0,Math.PI*2);ctx.fill();ctx.stroke();}if(f.type==='text'){ctx.fillStyle=f.color;ctx.font='bold 17px "Chakra Petch"';ctx.textAlign='center';ctx.fillText(f.text,f.x,f.y-(1-f.life/f.max)*30);}ctx.globalAlpha=1;}}
const htmlText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function renderScoreboard(){if(!game)return;$('scoreTeams').innerHTML=[game.player.team,1-game.player.team].map(team=>'<section class="score-team"><h3>'+ (team===game.player.team?'ทีมคุณ':'ศัตรู')+' · บอส '+(game.objectiveKills?.[team]||0)+'</h3><div class="score-head"><span>ฮีโร่ / ตำแหน่ง</span><span>LV</span><span>K/D/A</span><span>เงิน</span></div>'+game.entities.filter(e=>e.type==='hero'&&e.team===team).map(e=>'<div class="score-row'+(e.player?' score-you':'')+'"><div><b>'+htmlText((e.clientName||(e.player?'คุณ':'บอต'))+(e.autoPilot?' · บอตช่วยเล่น':''))+'</b><small>'+e.def.name+' · '+POSITIONS[e.position]+(e.dead?' · เกิด '+Math.ceil(e.respawn)+' วิ':'')+'</small><span class="score-items">'+e.inventory.map(i=>i.icon).join(' ')+'</span></div><span>'+e.level+'</span><span>'+e.kills+'/'+e.deaths+'/'+e.assists+'</span><span>'+Math.floor(e.gold)+' G</span></div>').join('')+'</section>').join('');}
$('scoreBtn').onclick=()=>{if(!game)return;keys.clear();joystick={x:0,y:0};renderScoreboard();$('scoreboard').showModal();};$('closeScore').onclick=()=>$('scoreboard').close();
function frame(now){const dt=Math.min(.05,(now-lastTime)/1000||0);lastTime=now;update(dt);draw();requestAnimationFrame(frame);}
function renderMini(){const w=120,h=80,x=view.width-w-12,y=88,s=w/WIDTH;ctx.fillStyle='#07121eea';ctx.fillRect(x,y,w,h);ctx.strokeStyle='#526779';ctx.lineWidth=1;ctx.strokeRect(x,y,w,h);for(const route of ROUTES){ctx.beginPath();route.forEach((p,i)=>i?ctx.lineTo(x+p[0]*s,y+p[1]*s):ctx.moveTo(x+p[0]*s,y+p[1]*s));ctx.strokeStyle='#3d5361';ctx.stroke();}for(const e of game.entities){if(e.dead||e.type==='minion')continue;ctx.fillStyle=e.player?'#fff':e.team===0?BLUE:e.team===1?RED:PURPLE;ctx.beginPath();ctx.arc(x+e.x*s,y+e.y*s,e.player?3.5:2,0,Math.PI*2);ctx.fill();}ctx.strokeStyle='#fff8';ctx.strokeRect(x+Math.max(0,-view.x/view.scale)*s,y+Math.max(0,-view.y/view.scale)*s,Math.min(WIDTH,view.width/view.scale)*s,Math.min(HEIGHT,view.height/view.scale)*s);}
$('shopBtn').onclick=()=>{if(!game||game.finished)return;const open=document.body.classList.toggle('shop-open');$('shopBtn').textContent=open?'ปิดร้าน':'ร้านค้า';if(typeof net!=='undefined'&&net.session){keys.clear();joystick={x:0,y:0};return;}if(open){shopPaused=!game.paused;if(shopPaused)pause(true);}else if(shopPaused){pause(false);shopPaused=false;}};
$('startBtn').onclick=startGame;$('pauseBtn').onclick=()=>pause(true);$('resumeBtn').onclick=()=>pause(false);$('exitBtn').onclick=$('againBtn').onclick=lobby;
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{const a=b.dataset.action;if(a==='attack')attackPlayer();else if(a==='recall')recall();else useSkill(a);});document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>buy(b.dataset.item));
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('help').open||document.body.classList.contains('shop-open'))return;const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'){if(game&&!game.finished)pause(typeof net!=='undefined'&&net.session&&!net.session.host?!net.localPause:!game.paused);return;}if(k==='tab'&&game){e.preventDefault();if($('scoreboard').open)$('scoreboard').close();else $('scoreBtn').onclick();return;}if($('scoreboard').open)return;keys.add(k);if(e.repeat)return;if(k==='q'||k==='e')useSkill(k);if(k==='shift')useSkill('w');if(k==='b')recall();});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());document.addEventListener('visibilitychange',()=>{if(document.hidden)pause(true);});
function canvasPoint(e){const r=canvas.getBoundingClientRect();return {x:(e.clientX-r.left-view.x)/view.scale,y:(e.clientY-r.top-view.y)/view.scale};}canvas.addEventListener('pointermove',e=>pointer=canvasPoint(e));canvas.addEventListener('pointerdown',e=>{if(!game||game.paused||game.finished||game.player.dead||e.button!==0)return;pointer=canvasPoint(e);game.player.destination={x:Math.max(45,Math.min(WIDTH-45,pointer.x)),y:Math.max(45,Math.min(HEIGHT-45,pointer.y))};game.player.recall=0;canvas.focus({preventScroll:true});});canvas.addEventListener('contextmenu',e=>{e.preventDefault();attackPlayer();});
let stickPointer=null;const stick=$('joystick');function updateStick(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,len=Math.hypot(dx,dy),factor=Math.min(1,35/(len||1));joystick={x:dx*factor/35,y:dy*factor/35};stick.firstElementChild.style.transform=`translate(${dx*factor}px,${dy*factor}px)`;}stick.onpointerdown=e=>{if(stickPointer!==null)return;stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e);};stick.onpointermove=e=>{if(e.pointerId===stickPointer)updateStick(e);};stick.onpointerup=stick.onpointercancel=e=>{if(e.pointerId!==stickPointer)return;stickPointer=null;joystick={x:0,y:0};stick.firstElementChild.style.transform='';};
$('soundBtn').onclick=()=>{sound=!sound;$('soundBtn').textContent='เสียง: '+(sound?'เปิด':'ปิด');$('soundBtn').setAttribute('aria-label',sound?'ปิดเสียง':'เปิดเสียง');if(sound)tone(540);};
let helpPaused=false;$('helpBtn').onclick=()=>{helpPaused=!!game&&!game.paused&&!game.finished;if(helpPaused)pause(true);$('help').showModal();};$('help').addEventListener('close',()=>{if(helpPaused)pause(false);helpPaused=false;});
const modelContext=document.modelContext;if(modelContext?.registerTool){const lifecycle=new AbortController();try{Promise.resolve(modelContext.registerTool({name:'read_match_state',description:'Read current match, selected hero, health, gold and result.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>game?{playing:!game.finished,paused:game.paused,time:Math.floor(game.time),hero:game.player.def.id,hp:game.player.hp,gold:Math.floor(game.player.gold),kills:game.kills,items:game.player.inventory.map(i=>i.id),teamBuffs:game.teamBuffs,objectives:game.entities.filter(e=>e.type==='monster').map(e=>({camp:e.camp,alive:!e.dead,respawn:Math.ceil(e.respawn)}))}:{playing:false,selectedHero:selected.id}},{signal:lifecycle.signal})).catch(()=>{});Promise.resolve(modelContext.registerTool({name:'buy_match_item',description:'Spend match gold to immediately buy an item into the current hero inventory.',inputSchema:{type:'object',properties:{itemId:{type:'string',enum:ITEMS.map(i=>i.id)}},required:['itemId'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input.itemId!=='string'||!ITEMS.some(i=>i.id===input.itemId))throw Error('Unknown item');return buy(input.itemId);}},{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
